/**
 * Presentable text for the simulated AI (AI_PROVIDER=fake): local demos and development.
 * Picks a template from the prompt's wording and fills in the topic; never calls any service.
 * Every answer ends with a visible note that it was not generated by a real model.
 */

export const DEMO_NOTE = "_Contenido de demostración (modo desarrollo): generado sin IA real y sin costo._";

const PATTERNS: [RegExp, (topic: string) => string][] = [
  [/Resume de forma clara:\s*([\s\S]+?)\.\s*Nivel/i, summary],
  [/explicación teórica profunda sobre:\s*([\s\S]+?)\.\s*Nivel/i, theory],
  [/ejercicios prácticos sobre:\s*([\s\S]+)/i, exercises],
  [/diagrama Mermaid sobre:\s*([\s\S]+)/i, diagram],
  [/guión de podcast educativo extenso sobre:\s*([\s\S]+?)\.\s*\n/i, podcast],
  [/guía de estudio del capítulo (\d+) del libro "([^"]+)"/i, (topic) => bookGuide(topic)],
  [/guía de estudio completa para el libro "([^"]+)"/i, (topic) => bookGuide(topic)],
];

/** Shortens the topic to something readable (prompts may embed whole documents). */
function cleanTopic(raw: string): string {
  const topic = raw.replace(/\s+/g, " ").trim().replace(/[."]+$/, "");
  return topic.length > 80 ? `${topic.slice(0, 77)}...` : topic || "el tema elegido";
}

export function demoText(prompt: string): string {
  for (const [pattern, render] of PATTERNS) {
    const match = pattern.exec(prompt);
    // Book chapter guides capture (chapter, title): use the title as the topic
    if (match) return `${render(cleanTopic(match[2] ? `${match[2]}, capítulo ${match[1]}` : match[1]))}\n\n${DEMO_NOTE}`;
  }
  return `${answer(prompt)}\n\n${DEMO_NOTE}`;
}

function summary(topic: string): string {
  return `## Resumen: ${topic}

**Idea central.** ${topic} se entiende mejor a partir de tres preguntas: qué es, por qué importa y cómo se aplica.

### Puntos clave
1. **Definición.** Qué abarca ${topic} y qué queda fuera.
2. **Conceptos principales.** Los términos que conviene dominar antes del examen.
3. **Relaciones.** Cómo se conecta con los temas anteriores del curso.
4. **Aplicaciones.** Situaciones concretas donde aparece.

### Para repasar
- Escribí una definición propia en una línea.
- Armá un ejemplo cotidiano.
- Identificá el error más común y cómo evitarlo.`;
}

function theory(topic: string): string {
  return `## Teoría: ${topic}

### 1. Fundamentos
${topic} parte de unos pocos principios. Entenderlos permite deducir el resto sin memorizar.

### 2. Desarrollo
- **Primer principio:** describe el comportamiento general.
- **Segundo principio:** explica las excepciones más frecuentes.
- **Tercer principio:** permite predecir resultados en casos nuevos.

### 3. Ejemplo guiado
Tomemos un caso simple de ${topic} y apliquemos cada principio paso a paso, verificando el resultado al final.

### 4. Errores frecuentes
- Confundir la causa con la consecuencia.
- Aplicar la regla general a un caso excepcional.`;
}

function exercises(topic: string): string {
  return `## Ejercicios: ${topic}

**Ejercicio 1 (básico).** Definí ${topic} con tus palabras y da un ejemplo.

**Ejercicio 2 (intermedio).** Compará dos situaciones donde aparece ${topic} y explicá la diferencia.

**Ejercicio 3 (avanzado).** Resolvé un caso nuevo aplicando los principios del tema y justificá cada paso.

<details><summary>Pistas</summary>

1. Empezá por los conceptos clave del resumen.
2. Hacé un esquema antes de responder.
3. Revisá si tu respuesta cubre las excepciones.
</details>`;
}

function diagram(topic: string): string {
  return `## Esquema: ${topic}

\`\`\`
${topic}
├── Conceptos clave
│   ├── Definición
│   └── Términos principales
├── Procesos
│   ├── Etapa 1: inicio
│   ├── Etapa 2: desarrollo
│   └── Etapa 3: resultado
└── Aplicaciones
    ├── Casos de la vida real
    └── Preguntas de examen
\`\`\``;
}

function podcast(topic: string): string {
  return `Hola, ¿cómo estás? Hoy vamos a hablar de ${topic}, así que ponete cómodo.

Escuchá bien esto: lo más importante de ${topic} es entender la idea central antes que los detalles. Como si estuviéramos en clase, vamos paso a paso.

Primero, la definición. Después, un ejemplo de todos los días. Y al final, lo que suele entrar en examen, así que prestá atención.

Para cerrar: repasá los puntos clave en voz alta y vas a ver que ${topic} se vuelve mucho más simple.`;
}

function bookGuide(topic: string): string {
  return `## Guía de lectura: ${topic}

### Resumen
En esta parte, la obra presenta a sus personajes principales y el conflicto que mueve la historia.

### Personajes e ideas
- **Protagonista:** sus decisiones y lo que revelan.
- **Conflicto central:** qué está en juego.

### Temas para analizar
1. El contexto histórico de la obra.
2. Los símbolos que se repiten.

### Preguntas para repasar
1. ¿Qué cambia en el protagonista?
2. ¿Qué papel cumple el escenario?
3. ¿Qué tema se anticipa para los capítulos siguientes?`;
}

function answer(prompt: string): string {
  // Plain text: the tutor and the assistant show answers without Markdown formatting
  const question = cleanTopic(prompt.split("\n").map((line) => line.trim()).filter(Boolean).pop() || "");
  return `Respuesta de prueba

Buena pregunta. Sobre "${question}", conviene pensarlo en tres pasos:

1. Entender el concepto: qué se pregunta y qué datos tenemos.
2. Aplicarlo: resolver un ejemplo concreto.
3. Verificar: comprobar el resultado y anotar la regla aprendida.

¿Querés que lo practiquemos con un ejercicio?`;
}

/** A few real places, so the map explorer shows something sensible in a demo. */
const PLACES: { match: RegExp; name: string; lat: number; lon: number }[] = [
  { match: /buenos aires/i, name: "Buenos Aires, Argentina", lat: -34.6037, lon: -58.3816 },
  { match: /par[ií]s/i, name: "París, Francia", lat: 48.8566, lon: 2.3522 },
  { match: /roma|coliseo/i, name: "Roma, Italia", lat: 41.8902, lon: 12.4922 },
  { match: /machu picchu|cusco/i, name: "Machu Picchu, Perú", lat: -13.1631, lon: -72.545 },
  { match: /tokio|tokyo/i, name: "Tokio, Japón", lat: 35.6762, lon: 139.6503 },
];

/** Answer for the map schema (name, lat, lon, weather, localTime, funFact); null for other schemas. */
export function demoLocation(schema: { properties?: Record<string, unknown> } | undefined, prompt: string): Record<string, unknown> | null {
  const keys = Object.keys(schema?.properties || {});
  if (!keys.includes("lat") || !keys.includes("lon")) return null;
  const query = /Busca información sobre:\s*([^.]+)\./i.exec(prompt)?.[1]?.trim();
  const coords = /Lat:\s*(-?\d+(?:\.\d+)?),\s*Lon:\s*(-?\d+(?:\.\d+)?)/i.exec(prompt);
  const known = PLACES.find((place) => query && place.match.test(query));
  const place = known
    || (coords ? { name: "Lugar seleccionado en el mapa", lat: Number(coords[1]), lon: Number(coords[2]) } : null)
    || { name: query ? cleanTopic(query) : "Buenos Aires, Argentina", lat: -34.6037, lon: -58.3816 };
  return {
    name: `${place.name} (modo desarrollo)`,
    lat: place.lat,
    lon: place.lon,
    weather: "22 °C, cielo despejado (simulado)",
    localTime: "14:30",
    funFact: "Dato curioso de demostración: en la versión real, la IA describe la historia y la geografía del lugar.",
  };
}
